// 提取内容数据
const results = $json.results || [];

if (results.length === 0) {
  throw new Error('没有待发布的公众号内容（状态需为

）');
}

const page = results[0];
const props = page.properties;

const content = {
  notionPageId: page.id,
  contentId: props['内容ID']?.rich_text?.[0]?.text?.content || '',
  title: props['标题']?.title?.[0]?.text?.content || '',
  content: props['完整正文']?.rich_text?.[0]?.text?.content || '',
  tags: props['话题标签']?.multi_select?.map(t => t.name) || [],
  imagesJson: props['配图建议']?.rich_text?.[0]?.text?.content || '[]'
};

// 解析图片
try {
  content.images = JSON.parse(content.imagesJson);
} catch (e) {
  content.images = [];
}

return [{ json: content }];

// 格式化公众号发布内容
const d = $json;

// 公众号正文格式化（Markdown转HTML）
let formattedContent = d.content;

// 添加版权声明
formattedContent += `\n\n---\n\n**原创声明**：本文为原创内容，未经授权禁止转载。\n\n**关注我们**：了解更多MBTI与生活方式的内容。`;

// 生成发布说明
const publishGuide = `【公众号发布指南】

方式1：公众号后台手动发布
1. 登录微信公众平台
2. 点击

方式2：使用第三方工具（推荐）
- 秀米编辑器：https://xiumi.us/
- 135编辑器：https://www.135editor.com/
- 新榜编辑器：https://edit.newrank.cn/

发布后请记录：
- 文章链接
- 文章ID
- 发布时间
- 阅读数（24小时后）`;

return [{
  json: {
    ...d,
    formattedContent,
    publishGuide,
    imageUrls: d.images.map(img => img.url).filter(url => url),
    imageCount: d.images.length
  }
}];

// 生成发布提示
const d = $json;

const message = `===========================================
公众号内容已准备就绪！
===========================================

【标题】
${d.title}

【正文】
${d.formattedContent}

【配图】
共${d.imageCount}张图片
封面图: ${d.imageUrls[0] || '无'}
${d.imageUrls.slice(1).map((url, i) => `配图${i+1}: ${url}`).join('\n')}

【话题标签】
${d.tags.join('、')}

${d.publishGuide}

===========================================`;

console.log(message);

return [{
  json: {
    ...d,
    publishMessage: message,
    status: '待人工发布'
  }
}];

