const summary = `公众号发布准备报告
===================
执行时间: ${new Date().toLocaleString('zh-CN')}

【内容信息】
- 内容ID: ${d.contentId}
- 标题: ${d.title}
- 字数: ${d.content.length}字
- 配图: ${d.imageCount}张
- 话题标签: ${d.tags.join('、')}

【发布内容】
${d.publishMessage}

